// Stolen from https://alexwlchan.net/2025/localising-the-time/
// and https://alexwlchan.net/2020/human-friendly-dates-in-javascript/

const dateFormatter = new Intl.DateTimeFormat(
  ["nl-NL"], {"year": "numeric", "month": "long", "day": "numeric"}
)

const timeFormatter = new Intl.DateTimeFormat(
  ["nl-NL"], {"hour": "numeric", "minute": "numeric"}
)

function localizeTimes(root) {
  const nodes = root.matches("time[local]")
    ? [root] : root.querySelectorAll("time[local]");

  nodes.forEach((time) => {
    const timestamp = time.getAttribute("datetime") || time.innerText;
    time.setAttribute("title", time.innerText);
    time.innerText = getHumanFriendlyDateString(timestamp);
  });
}

window.addEventListener("DOMContentLoaded", function() {
  localizeTimes(document.body);

  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType === 1) localizeTimes(node);
      });
    });
  });

  observer.observe(document.body, {
    childList: true,
    subtree: true,
  });
});

function getHumanFriendlyDateString(str) {
  const date = new Date(str);

  const today = new Date();
  const yesterday = new Date().setDate(today.getDate() - 1);

  // We have to compare the *formatted* dates rather than the actual dates --
  // for example, if the UTC date and the localised date fall on either side
  // of midnight.
  if (dateFormatter.format(date) == dateFormatter.format(today)) {
    return "today " + timeFormatter.format(date);
  }
  else if (dateFormatter.format(date) == dateFormatter.format(yesterday)) {
    return "yesterday " + timeFormatter.format(date);
  }
  else {
    return dateFormatter.format(date) + " " + timeFormatter.format(date);
  }
}

function getHumanFriendlyDelta(str) {
  const date = new Date(Date.parse(str));
  const now = new Date();

  const deltaMilliseconds = now - date;
  const deltaSeconds = Math.floor(deltaMilliseconds / 1000);
  const deltaMinutes = Math.floor(deltaSeconds / 60);
  const deltaHours = Math.floor(deltaMinutes / 60);

  if (deltaSeconds < 5) return "just now";
  else if (deltaSeconds < 60) return deltaSeconds + " seconds ago";
  else if (deltaMinutes == 1) return "1 minute ago";
  else if (deltaMinutes < 60) return deltaMinutes + " minutes ago";
  else if (deltaHours == 1) return "1 hour ago";
  else if (deltaHours < 6) return deltaHours + " hours ago";
  else return "";
}
